def compatibleMass (N : Finset ℕ) (beta : ℕ → ℂ) (q r : ℕ) : ℂ :=
  ∑ n₁ ∈ N, ∑ n₂ ∈ N,
    if ComplexCRT.Compatible q r n₁ n₂ then beta n₁ * star (beta n₂) else 0
